#include "ezlocalai/native_server.hpp"
#include "ezlocalai/environment_defaults.hpp"
#include "ezlocalai/stt_runtime.hpp"
#include "whisper_transcription_test.hpp"
using namespace transcription_test;
std::string hex(const std::string &value){std::string out;for(unsigned char c:value){out+="0123456789abcdef"[c>>4];out+="0123456789abcdef"[c&15];}return out;}
int main(int argc,char **argv){try{
    expect(argc==3,"source and data-URI API fixture");const auto cases=records(argv[2]);expect(hash(read(fs::path(argv[1])/"app.py"))==cases[0].at("source_sha256")&&hash(read(fs::path(argv[1])/"Pipes.py"))==cases[0].at("pipes_sha256"),"unchanged endpoint and pipeline");expect(cases.size()-1==cases[0].at("cases"),"complete API fixture");
    Temporary temporary;struct Restore{fs::path path=fs::current_path();~Restore(){fs::current_path(path);}}restore;fs::current_path(temporary.path);
    for(size_t i=1;i<cases.size();++i){const auto &row=cases[i];const auto config=row.at("config");Json calls=Json::array();
        for(const auto &entry:environment_defaults)setenv(std::string(entry.first).c_str(),std::string(entry.second).c_str(),1);
        for(const auto &[key,value]:std::map<std::string,std::string>{{"EZLOCALAI_API_KEY",""},{"DEFAULT_MODEL","fixture-text"},{"WHISPER_MODEL","fixture-model"},{"STT_N_PARALLEL","1"},{"TTS_N_PARALLEL","1"},{"STT_UNLOAD_LLM_DURING_GENERATION","false"},{"TTS_UNLOAD_LLM_DURING_GENERATION","false"},{"LAZY_LOAD_VOICE","true"},{"VOICE_SERVER",config.value("voice_server","http://127.0.0.1:1")},{"TTS_ENABLED",config.value("enabled","true")},{"EZLOCALAI_URL",config.value("local_uri","http://host/")},{"ROUTER_URL",""},{"FALLBACK_SERVER",""}})setenv(key.c_str(),value.c_str(),1);
        auto probes=native_resource_probes();probes.gpu_count=[]{return 0;};probes.total_per_gpu=[]{return std::vector<double>{};};probes.system_ram=[]{return 16.;};auto resources=std::make_shared<ResourceManager>(probes);
        SttPoolFactory stt=[&](auto manager){auto ops=stt_pool_resources({},manager);ops.schedule_cleanup=[](auto work){work();};ops.load=[&](const auto &){if(config.contains("stt_get_error"))throw SttError("RuntimeError",config.at("stt_get_error"));auto model=std::make_shared<SttPoolModel>();model->device=[]{return "cpu";};model->close=[]{ };model->transcribe_bytes=[&](const auto &request,const auto &audio){calls.push_back({{"op","transcribe"},{"hex",hex(audio)},{"format",Json::parse(request).at("audio_format")}});if(config.contains("stt_error"))throw SttError(config.value("stt_category","RuntimeError"),config.at("stt_error"));return config.value("text",Json("transcript")).dump();};return model;};return ops;};
        TtsPoolFactory tts=[&](auto manager){auto ops=tts_pool_resources({},manager);ops.schedule_cleanup=[](auto work){work();};ops.can_load=[]{return ModelAdmission{true,"cpu","fixture"};};ops.load=[&](const auto &){if(config.contains("tts_get_error"))throw TtsError("RuntimeError",config.at("tts_get_error"));auto model=std::make_shared<TtsPoolModel>();model->device=[]{return "cpu";};model->close=[]{ };model->generate=[&](const auto &request){calls.push_back({{"op","generate"},{"request",Json::parse(request)}});if(config.contains("tts_error"))throw TtsError("RuntimeError",config.at("tts_error"));return config.value("result",std::string("YWJj"));};return model;};return ops;};
        ezl_env_config environment{};ezl_load_config(&environment);NativeServer server(environment,std::make_unique<EchoInferenceBackend>("fixture-text"),resources,stt,tts,{},true);
        const auto result=server.handle_request("POST","/v1/audio/speech","",row.at("body"),"application/json");const auto label="audio pipeline API "+std::to_string(i);
        compare_json(result.status,row.at("status"),label+" status");compare_json(result.content_type,row.at("headers").at("content-type"),label+" content type");const auto source=unhex(row.at("hex"));if(result.content_type=="application/json")compare_json(Json::parse(result.body),Json::parse(source),label+" response");else compare_json(result.body,source,label+" error response");
        Json expected=Json::array();for(const auto &call:row.at("calls"))if(call.at("op")=="transcribe"||call.at("op")=="generate")expected.push_back(call);compare_json(calls,expected,label+" local model input and order");expect(server.tts_permits()->available==1,label+" voice permit released");
    }
    std::cout<<cases.size()-1<<" source audio data-URI API cases match local model calls, byte inputs, responses and errors\n";return 0;
}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}}
